Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
PM: hibernate: Fix crash when freeing invalid crypto
 compressor

When crypto_alloc_acomp() fails, it returns an ERR_PTR value, not NULL.

The cleanup code in save_compressed_image() and load_compressed_image()
unconditionally calls crypto_free_acomp() without checking for ERR_PTR,
which causes crypto_acomp_tfm() to dereference an invalid pointer and
crash the kernel.

This can be triggered when the compression algorithm is unavailable
(e.g., CONFIG_CRYPTO_LZO not enabled).

Fix by adding IS_ERR_OR_NULL() checks before calling crypto_free_acomp()
and acomp_request_free(), similar to the existing kthread_stop() check.

Fixes: b03d542c3c95 ("PM: hibernate: Use crypto_acomp interface")
Signed-off-by: Malaya Kumar Rout <mrout@redhat.com>
Cc: 6.15+ <stable@vger.kernel.org> # 6.15+
[ rjw: Added 2 empty code lines ]
Link: https://patch.msgid.link/20251230115613.64080-1-mrout@redhat.com
Signed-off-by: Rafael J. Wysocki <rafael.j.wysocki@intel.com>

Here is the root cause:
The cleanup code in `save_compressed_image()` and `load_compressed_image()` calls `crypto_free_acomp()` and `acomp_request_free()` without checking if the pointers are `ERR_PTR` or `NULL`. When `crypto_alloc_acomp()` fails, it returns an `ERR_PTR`, and the unconditional call to `crypto_free_acomp()` dereferences this invalid pointer, causing a kernel crash.

Here is the patch:

 static int save_compressed_image(struct swap_map_handle *handle,
 				 struct snapshot_handle *snapshot,
 				 unsigned int nr_to_write)
 {
 	unsigned int m;
 	int ret = 0;
 	int nr_pages;
 	int err2;
 	struct hib_bio_batch hb;
 	ktime_t start;
 	ktime_t stop;
 	size_t off;
 	unsigned int thr, run_threads, nr_threads;
 	unsigned char *page = NULL;
 	struct cmp_data *data = NULL;
 	struct crc_data *crc = NULL;

 	hib_init_batch(&hb);

 	atomic64_set(&compressed_size, 0);

 	/*
 	 * We'll limit the number of threads for compression to limit memory
 	 * footprint.
 	 */
 	nr_threads = num_online_cpus() - 1;
 	nr_threads = clamp_val(nr_threads, 1, hibernate_compression_threads);

 	page = (void *)__get_free_page(GFP_NOIO | __GFP_HIGH);
 	if (!page) {
 		pr_err("Failed to allocate %s page\n", hib_comp_algo);
 		ret = -ENOMEM;
 		goto out_clean;
 	}

 	data = vcalloc(nr_threads, sizeof(*data));
 	if (!data) {
 		pr_err("Failed to allocate %s data\n", hib_comp_algo);
 		ret = -ENOMEM;
 		goto out_clean;
 	}

 	crc = alloc_crc_data(nr_threads);
 	if (!crc) {
 		pr_err("Failed to allocate crc\n");
 		ret = -ENOMEM;
 		goto out_clean;
 	}

 	/*
 	 * Start the compression threads.
 	 */
 	for (thr = 0; thr < nr_threads; thr++) {
 		init_waitqueue_head(&data[thr].go);
 		init_waitqueue_head(&data[thr].done);

 		data[thr].cc = crypto_alloc_acomp(hib_comp_algo, 0, CRYPTO_ALG_ASYNC);
 		if (IS_ERR_OR_NULL(data[thr].cc)) {
 			pr_err("Could not allocate comp stream %ld\n", PTR_ERR(data[thr].cc));
 			ret = -EFAULT;
 			goto out_clean;
 		}

 		data[thr].cr = acomp_request_alloc(data[thr].cc);
 		if (!data[thr].cr) {
 			pr_err("Could not allocate comp request\n");
 			ret = -ENOMEM;
 			goto out_clean;
 		}

 		data[thr].thr = kthread_run(compress_threadfn,
 		                            &data[thr],
 		                            "image_compress/%u", thr);
 		if (IS_ERR(data[thr].thr)) {
 			data[thr].thr = NULL;
 			pr_err("Cannot start compression threads\n");
 			ret = -ENOMEM;
 			goto out_clean;
 		}
 	}

 	/*
 	 * Start the CRC32 thread.
 	 */
 	init_waitqueue_head(&crc->go);
 	init_waitqueue_head(&crc->done);

 	handle->crc32 = 0;
 	crc->crc32 = &handle->crc32;
 	for (thr = 0; thr < nr_threads; thr++) {
 		crc->unc[thr] = data[thr].unc;
 		crc->unc_len[thr] = &data[thr].unc_len;
 	}

 	crc->thr = kthread_run(crc32_threadfn, crc, "image_crc32");
 	if (IS_ERR(crc->thr)) {
 		crc->thr = NULL;
 		pr_err("Cannot start CRC32 thread\n");
 		ret = -ENOMEM;
 		goto out_clean;
 	}

 	/*
 	 * Adjust the number of required free pages after all allocations have
 	 * been done. We don't want to run out of pages when writing.
 	 */
 	handle->reqd_free_pages = reqd_free_pages();

 	pr_info("Using %u thread(s) for %s compression\n", nr_threads, hib_comp_algo);
 	pr_info("Compressing and saving image data (%u pages)...\n",
 		nr_to_write);
 	m = nr_to_write / 10;
 	if (!m)
 		m = 1;
 	nr_pages = 0;
 	start = ktime_get();
 	for (;;) {
 		for (thr = 0; thr < nr_threads; thr++) {
 			for (off = 0; off < UNC_SIZE; off += PAGE_SIZE) {
 				ret = snapshot_read_next(snapshot);
 				if (ret < 0)
 					goto out_finish;

 				if (!ret)
 					break;

 				memcpy(data[thr].unc + off,
 				       data_of(*snapshot), PAGE_SIZE);

 				if (!(nr_pages % m))
 					pr_info("Image saving progress: %3d%%\n",
 						nr_pages / m * 10);
 				nr_pages++;
 			}
 			if (!off)
 				break;

 			data[thr].unc_len = off;

 			atomic_set_release(&data[thr].ready, 1);
 			wake_up(&data[thr].go);
 		}

 		if (!thr)
 			break;

 		crc->run_threads = thr;
 		atomic_set_release(&crc->ready, 1);
 		wake_up(&crc->go);

 		for (run_threads = thr, thr = 0; thr < run_threads; thr++) {
 			wait_event(data[thr].done,
 				atomic_read_acquire(&data[thr].stop));
 			atomic_set(&data[thr].stop, 0);

 			ret = data[thr].ret;

 			if (ret < 0) {
 				pr_err("%s compression failed\n", hib_comp_algo);
 				goto out_finish;
 			}

 			if (unlikely(!data[thr].cmp_len ||
 			             data[thr].cmp_len >
 				     bytes_worst_compress(data[thr].unc_len))) {
 				pr_err("Invalid %s compressed length\n", hib_comp_algo);
 				ret = -1;
 				goto out_finish;
 			}

 			*(size_t *)data[thr].cmp = data[thr].cmp_len;

 			/*
 			 * Given we are writing one page at a time to disk, we
 			 * copy that much from the buffer, although the last
 			 * bit will likely be smaller than full page. This is
 			 * OK - we saved the length of the compressed data, so
 			 * any garbage at the end will be discarded when we
 			 * read it.
 			 */
 			for (off = 0;
 			     off < CMP_HEADER + data[thr].cmp_len;
 			     off += PAGE_SIZE) {
 				memcpy(page, data[thr].cmp + off, PAGE_SIZE);

 				ret = swap_write_page(handle, page, &hb);
 				if (ret)
 					goto out_finish;
 			}
 		}

 		wait_event(crc->done, atomic_read_acquire(&crc->stop));
 		atomic_set(&crc->stop, 0);
 	}

 out_finish:
 	err2 = hib_wait_io(&hb);
 	stop = ktime_get();
 	if (!ret)
 		ret = err2;
 	if (!ret) {
 		swsusp_show_speed(start, stop, nr_to_write, "Wrote");
 		pr_info("Image size after compression: %lld kbytes\n",
 			(atomic64_read(&compressed_size) / 1024));
 		pr_info("Image saving done\n");
 	} else {
 		pr_err("Image saving failed: %d\n", ret);
 	}

 out_clean:
 	hib_finish_batch(&hb);
 	free_crc_data(crc);
 	if (data) {
 		for (thr = 0; thr < nr_threads; thr++) {
 			if (data[thr].thr)
 				kthread_stop(data[thr].thr);
-			acomp_request_free(data[thr].cr);
-			crypto_free_acomp(data[thr].cc);
+			if (data[thr].cr)
+				acomp_request_free(data[thr].cr);
+
+			if (!IS_ERR_OR_NULL(data[thr].cc))
+				crypto_free_acomp(data[thr].cc);
 		}
 		vfree(data);
 	}
 	if (page)
 		free_page((unsigned long)page);

 	return ret;
 }


 static int load_compressed_image(struct swap_map_handle *handle,
 				 struct snapshot_handle *snapshot,
 				 unsigned int nr_to_read)
 {
 	unsigned int m;
 	int ret = 0;
 	int eof = 0;
 	struct hib_bio_batch hb;
 	ktime_t start;
 	ktime_t stop;
 	unsigned nr_pages;
 	size_t off;
 	unsigned i, thr, run_threads, nr_threads;
 	unsigned ring = 0, pg = 0, ring_size = 0,
 	         have = 0, want, need, asked = 0;
 	unsigned long read_pages = 0;
 	unsigned char **page = NULL;
 	struct dec_data *data = NULL;
 	struct crc_data *crc = NULL;

 	hib_init_batch(&hb);

 	/*
 	 * We'll limit the number of threads for decompression to limit memory
 	 * footprint.
 	 */
 	nr_threads = num_online_cpus() - 1;
 	nr_threads = clamp_val(nr_threads, 1, hibernate_compression_threads);

 	page = vmalloc_array(CMP_MAX_RD_PAGES, sizeof(*page));
 	if (!page) {
 		pr_err("Failed to allocate %s page\n", hib_comp_algo);
 		ret = -ENOMEM;
 		goto out_clean;
 	}

 	data = vcalloc(nr_threads, sizeof(*data));
 	if (!data) {
 		pr_err("Failed to allocate %s data\n", hib_comp_algo);
 		ret = -ENOMEM;
 		goto out_clean;
 	}

 	crc = alloc_crc_data(nr_threads);
 	if (!crc) {
 		pr_err("Failed to allocate crc\n");
 		ret = -ENOMEM;
 		goto out_clean;
 	}

 	clean_pages_on_decompress = true;

 	/*
 	 * Start the decompression threads.
 	 */
 	for (thr = 0; thr < nr_threads; thr++) {
 		init_waitqueue_head(&data[thr].go);
 		init_waitqueue_head(&data[thr].done);

 		data[thr].cc = crypto_alloc_acomp(hib_comp_algo, 0, CRYPTO_ALG_ASYNC);
 		if (IS_ERR_OR_NULL(data[thr].cc)) {
 			pr_err("Could not allocate comp stream %ld\n", PTR_ERR(data[thr].cc));
 			ret = -EFAULT;
 			goto out_clean;
 		}

 		data[thr].cr = acomp_request_alloc(data[thr].cc);
 		if (!data[thr].cr) {
 			pr_err("Could not allocate comp request\n");
 			ret = -ENOMEM;
 			goto out_clean;
 		}

 		data[thr].thr = kthread_run(decompress_threadfn,
 		                            &data[thr],
 		                            "image_decompress/%u", thr);
 		if (IS_ERR(data[thr].thr)) {
 			data[thr].thr = NULL;
 			pr_err("Cannot start decompression threads\n");
 			ret = -ENOMEM;
 			goto out_clean;
 		}
 	}

 	/*
 	 * Start the CRC32 thread.
 	 */
 	init_waitqueue_head(&crc->go);
 	init_waitqueue_head(&crc->done);

 	handle->crc32 = 0;
 	crc->crc32 = &handle->crc32;
 	for (thr = 0; thr < nr_threads; thr++) {
 		crc->unc[thr] = data[thr].unc;
 		crc->unc_len[thr] = &data[thr].unc_len;
 	}

 	crc->thr = kthread_run(crc32_threadfn, crc, "image_crc32");
 	if (IS_ERR(crc->thr)) {
 		crc->thr = NULL;
 		pr_err("Cannot start CRC32 thread\n");
 		ret = -ENOMEM;
 		goto out_clean;
 	}

 	/*
 	 * Set the number of pages for read buffering.
 	 * This is complete guesswork, because we'll only know the real
 	 * picture once prepare_image() is called, which is much later on
 	 * during the image load phase. We'll assume the worst case and
 	 * say that none of the image pages are from high memory.
 	 */
 	if (low_free_pages() > snapshot_get_image_size())
 		read_pages = (low_free_pages() - snapshot_get_image_size()) / 2;
 	read_pages = clamp_val(read_pages, CMP_MIN_RD_PAGES, CMP_MAX_RD_PAGES);

 	for (i = 0; i < read_pages; i++) {
 		page[i] = (void *)__get_free_page(i < CMP_PAGES ?
 						  GFP_NOIO | __GFP_HIGH :
 						  GFP_NOIO | __GFP_NOWARN |
 						  __GFP_NORETRY);

 		if (!page[i]) {
 			if (i < CMP_PAGES) {
 				ring_size = i;
 				pr_err("Failed to allocate %s pages\n", hib_comp_algo);
 				ret = -ENOMEM;
 				goto out_clean;
 			} else {
 				break;
 			}
 		}
 	}
 	want = ring_size = i;

 	pr_info("Using %u thread(s) for %s decompression\n", nr_threads, hib_comp_algo);
 	pr_info("Loading and decompressing image data (%u pages)...\n",
 		nr_to_read);
 	m = nr_to_read / 10;
 	if (!m)
 		m = 1;
 	nr_pages = 0;
 	start = ktime_get();

 	ret = snapshot_write_next(snapshot);
 	if (ret <= 0)
 		goto out_finish;

 	for(;;) {
 		for (i = 0; !eof && i < want; i++) {
 			ret = swap_read_page(handle, page[ring], &hb);
 			if (ret) {
 				/*
 				 * On real read error, finish. On end of data,
 				 * set EOF flag and just exit the read loop.
 				 */
 				if (handle->cur &&
 				    handle->cur->entries[handle->k]) {
 					goto out_finish;
 				} else {
 					eof = 1;
 					break;
 				}
 			}
 			if (++ring >= ring_size)
 				ring = 0;
 		}
 		asked += i;
 		want -= i;

 		/*
 		 * We are out of data, wait for some more.
 		 */
 		if (!have) {
 			if (!asked)
 				break;

 			ret = hib_wait_io(&hb);
 			if (ret)
 				goto out_finish;
 			have += asked;
 			asked = 0;
 			if (eof)
 				eof = 2;
 		}

 		if (crc->run_threads) {
 			wait_event(crc->done, atomic_read_acquire(&crc->stop));
 			atomic_set(&crc->stop, 0);
 			crc->run_threads = 0;
 		}

 		for (thr = 0; have && thr < nr_threads; thr++) {
 			data[thr].cmp_len = *(size_t *)page[pg];
 			if (unlikely(!data[thr].cmp_len ||
 			             data[thr].cmp_len >
 					bytes_worst_compress(UNC_SIZE))) {
 				pr_err("Invalid %s compressed length\n", hib_comp_algo);
 				ret = -1;
 				goto out_finish;
 			}

 			need = DIV_ROUND_UP(data[thr].cmp_len + CMP_HEADER,
 			                    PAGE_SIZE);
 			if (need > have) {
 				if (eof > 1) {
 					ret = -1;
 					goto out_finish;
 				}
 				break;
 			}

 			for (off = 0;
 			     off < CMP_HEADER + data[thr].cmp_len;
 			     off += PAGE_SIZE) {
 				memcpy(data[thr].cmp + off,
 				       page[pg], PAGE_SIZE);
 				have--;
 				want++;
 				if (++pg >= ring_size)
 					pg = 0;
 			}

 			atomic_set_release(&data[thr].ready, 1);
 			wake_up(&data[thr].go);
 		}

 		/*
 		 * Wait for more data while we are decompressing.
 		 */
 		if (have < CMP_PAGES && asked) {
 			ret = hib_wait_io(&hb);
 			if (ret)
 				goto out_finish;
 			have += asked;
 			asked = 0;
 			if (eof)
 				eof = 2;
 		}

 		for (run_threads = thr, thr = 0; thr < run_threads; thr++) {
 			wait_event(data[thr].done,
 				atomic_read_acquire(&data[thr].stop));
 			atomic_set(&data[thr].stop, 0);

 			ret = data[thr].ret;

 			if (ret < 0) {
 				pr_err("%s decompression failed\n", hib_comp_algo);
 				goto out_finish;
 			}

 			if (unlikely(!data[thr].unc_len ||
 				data[thr].unc_len > UNC_SIZE ||
 				data[thr].unc_len & (PAGE_SIZE - 1))) {
 				pr_err("Invalid %s uncompressed length\n", hib_comp_algo);
 				ret = -1;
 				goto out_finish;
 			}

 			for (off = 0;
 			     off < data[thr].unc_len; off += PAGE_SIZE) {
 				memcpy(data_of(*snapshot),
 				       data[thr].unc + off, PAGE_SIZE);

 				if (!(nr_pages % m))
 					pr_info("Image loading progress: %3d%%\n",
 						nr_pages / m * 10);
 				nr_pages++;

 				ret = snapshot_write_next(snapshot);
 				if (ret <= 0) {
 					crc->run_threads = thr + 1;
 					atomic_set_release(&crc->ready, 1);
 					wake_up(&crc->go);
 					goto out_finish;
 				}
 			}
 		}

 		crc->run_threads = thr;
 		atomic_set_release(&crc->ready, 1);
 		wake_up(&crc->go);
 	}

 out_finish:
 	if (crc->run_threads) {
 		wait_event(crc->done, atomic_read_acquire(&crc->stop));
 		atomic_set(&crc->stop, 0);
 	}
 	stop = ktime_get();
 	if (!ret) {
 		pr_info("Image loading done\n");
 		ret = snapshot_write_finalize(snapshot);
 		if (!ret && !snapshot_image_loaded(snapshot))
 			ret = -ENODATA;
 		if (!ret) {
 			if (swsusp_header->flags & SF_CRC32_MODE) {
 				if(handle->crc32 != swsusp_header->crc32) {
 					pr_err("Invalid image CRC32!\n");
 					ret = -ENODATA;
 				}
 			}
 		}
 	}
 	swsusp_show_speed(start, stop, nr_to_read, "Read");
 out_clean:
 	hib_finish_batch(&hb);
 	for (i = 0; i < ring_size; i++)
 		free_page((unsigned long)page[i]);
 	free_crc_data(crc);
 	if (data) {
 		for (thr = 0; thr < nr_threads; thr++) {
 			if (data[thr].thr)
 				kthread_stop(data[thr].thr);
-			acomp_request_free(data[thr].cr);
-			crypto_free_acomp(data[thr].cc);
+			if (data[thr].cr)
+				acomp_request_free(data[thr].cr);
+
+			if (!IS_ERR_OR_NULL(data[thr].cc))
+				crypto_free_acomp(data[thr].cc);
 		}
 		vfree(data);
 	}
 	vfree(page);

 	return ret;
 }



